  "hypothesis": "Replacing the five fixed mixture weights with a peak-aware continuous line search will find beneficial conservative remeshings that coarse mixture sampling misses, with a target gain of at least 1e-5.",
  "rationale": "The score has kinks when the maximizing convolution lag changes, so its best mixture weight need not lie near the parent's fixed choices. Along each remeshing direction, the numerator is quartic and every convolution sample is quadratic; using these formulas makes a finer search inexpensive while retaining full-convolution checks and exact verifier acceptance.",
  "source": "import time
import numpy as np
from scipy.fft import rfft, irfft, next_fast_len
from scipy.signal import oaconvolve
from scipy.optimize import minimize_scalar

PARAMS = {
    'proposals': (24, 6, 64),
    'width_step': (1.0, 0.25, 8.0),
    'reserve': (0.70, 0.5, 0.75)
}

def construct(params, seed, budget_s, init=None):
    start = time.monotonic()
    deadline = start + float(params['reserve']) * budget_s
    rng = np.random.default_rng(seed)
    def alive(margin=0.0):
        return time.monotonic() + margin < deadline
    def exact(f):
        z = np.maximum(f, 0.0)
        conv = oaconvolve(z, z, mode='full')
        m = len(conv)
        dx = np.diff(np.linspace(-0.5, 0.5, m + 2))
        y = np.concatenate(([0.0], conv, [0.0]))
        numerator = float(np.sum((dx / 3.0) * (y[:-1]**2 + y[:-1]*y[1:] + y[1:]**2)))
        return numerator / ((np.sum(np.abs(conv))/(m+1))*np.max(np.abs(conv)))
    def fast_score(conv):
        return float((2*np.dot(conv,conv)+np.dot(conv[:-1],conv[1:])) / (3*np.sum(np.abs(conv))*np.max(np.abs(conv))))
    if init is None:
        return {'length': 1, 'packets': [[0, [1.0]]]}
    if 'values' in init:
        raw = init['values']
    else:
        raw = np.zeros(int(init['length']))
        for a, v in init['packets']:
            if not alive(3):
                return init
            raw[int(a):int(a)+len(v)] += np.asarray(v)
    f = np.maximum(np.asarray(raw, dtype=np.float64), 0.0)
    baseline = exact(f)
    if not alive(6) or len(f) < 4:
        return init
    n = len(f)
    f = f / np.max(f)
    edges = np.diff(np.r_[False, f > 0, False].astype(np.int8))
    aa = np.flatnonzero(edges == 1)
    bb = np.flatnonzero(edges == -1)
    if len(aa) < 2:
        return init
    mass = np.r_[0.0, np.cumsum(f)]
    heavy = int(np.argmax(mass[bb]-mass[aa]))
    prefixes = []
    for a, b in zip(aa, bb):
        if not alive(6):
            return init
        prefixes.append(np.r_[0.0, np.cumsum(f[a:b])])
    nc = 2*n-1
    L = next_fast_len(nc)
    F = rfft(f, L, workers=1)
    c = irfft(F*F, L, workers=1)[:nc]
    best_score = baseline
    best = None
    step = float(params['width_step'])
    specs = []
    for delta in (step, -step, 2*step, -2*step, 4*step, -4*step):
        if not alive(5):
            return init
        for anchor in (0.5, 0.0, 1.0):
            if not alive(5):
                return init
            specs.append((delta, anchor, 0))
    specs += [(step,0.5,1),(-step,0.5,1),(2*step,0.5,2),(-2*step,0.5,2),(.20,0.5,3),(-.20,0.5,3)]
    for j in range(max(0,int(params['proposals'])-len(specs))):
        if not alive(5):
            break
        specs.append((float(rng.choice([-1,1]))*step*float(rng.uniform(.5,5)), float(rng.choice([0,.5,1])), int(rng.integers(0,3))))

    def bilinear(x, y):
        return float(2*np.dot(x,y) + .5*np.dot(x[:-1],y[1:]) + .5*np.dot(x[1:],y[:-1]))

    q0 = bilinear(c,c)
    s0 = float(np.sum(c))
    # Continuously optimize a quadratic convolution path using a small,
    # adaptively augmented envelope of potentially active peak samples.
    def mixture_search(cd, dd):
        if not alive(5):
            return []
        poly = np.array([q0, 2*bilinear(c,cd), bilinear(cd,cd)+2*bilinear(c,dd), 2*bilinear(cd,dd), bilinear(dd,dd)])
        sums = np.array([s0, np.sum(cd), np.sum(dd)], dtype=float)
        grid = np.unique(np.r_[0.0, np.geomspace(1e-9, 1.0, 37), np.linspace(0,1,17)])
        active = set()
        for a in (0.0, .03125, .125, .25, .5, .75, 1.0):
            if not alive(4):
                return []
            cc = c+a*cd+a*a*dd
            k = min(24, len(cc))
            active.update(np.argpartition(cc, len(cc)-k)[-k:].tolist())
        candidates = []
        for iteration in range(3):
            if not alive(3.5):
                break
            ix = np.fromiter(sorted(active), dtype=np.int64)
            p0, p1, p2 = c[ix], cd[ix], dd[ix]
            def objective(a):
                if not alive(2.5):
                    return 1e100
                numerator = np.polynomial.polynomial.polyval(a, poly)
                total = sums[0]+a*sums[1]+a*a*sums[2]
                peak = np.max(p0+a*p1+a*a*p2)
                if peak <= 0 or total <= 0:
                    return 1e100
                return -float(numerator/(3*total*peak))
            vals = []
            for a in grid:
                if not alive(3):
                    break
                vals.append((objective(float(a)), float(a)))
            if not vals:
                break
            vals.sort()
            trials = [a for _,a in vals[:4]]
            for _, a in vals[:3]:
                if not alive(3):
                    break
                j = int(np.searchsorted(grid,a))
                lo = float(grid[max(0,j-1)])
                hi = float(grid[min(len(grid)-1,j+1)])
                if hi > lo:
                    opt = minimize_scalar(objective, bounds=(lo,hi), method='bounded', options={'xatol':1e-13, 'maxiter':55})
                    trials.append(float(opt.x))
            trials = sorted(set(trials), key=objective)[:3]
            added = False
            for a in trials:
                if not alive(3):
                    break
                cc = c+a*cd+a*a*dd
                score = fast_score(cc)
                candidates.append((score,a))
                peak = int(np.argmax(cc))
                if peak not in active:
                    active.add(peak)
                    added = True
            if not added:
                break
        return sorted(candidates, reverse=True)

    for delta, anchor, mode in specs[:int(params['proposals'])]:
        if not alive(7):
            break
        g = np.zeros(n, dtype=np.float64)
        complete = True
        for j, (a,b) in enumerate(zip(aa,bb)):
            if not alive(6):
                complete = False
                break
            a,b = int(a),int(b)
            w = b-a
            if j == heavy:
                g[a:b] += f[a:b]
                continue
            x = (a+b)/(2.0*n)
            if mode == 1:
                change = delta*(2*x-1)
            elif mode == 2:
                change = delta*np.cos(2*np.pi*x)
            elif mode == 3:
                change = delta*w
            else:
                change = delta
            new_w = max(.25,w+change)
            left = a-anchor*(new_w-w)
            right = left+new_w
            if left < 0:
                right -= left
                left = 0.0
            if right > n:
                left -= right-n
                right = float(n)
            left = max(0.0,left)
            actual = right-left
            if actual <= 0:
                complete = False
                break
            lo = max(0,int(np.floor(left)))
            hi = min(n,int(np.ceil(right)))
            boundaries = np.arange(lo,hi+1,dtype=np.float64)
            old_coordinate = np.clip((boundaries-left)*(w/actual),0.0,float(w))
            ix = np.minimum(np.floor(old_coordinate).astype(np.int64),w-1)
            integral = prefixes[j][ix] + (old_coordinate-ix)*f[a+ix]
            g[lo:hi] += np.maximum(np.diff(integral),0.0)
        if not complete or not alive(6):
            break
        d = g-f
        D = rfft(d,L,workers=1)
        cd = 2*irfft(F*D,L,workers=1)[:nc]
        dd = irfft(D*D,L,workers=1)[:nc]
        candidates = mixture_search(cd,dd)
        for score, alpha in candidates[:2]:
            if not alive(2.5):
                break
            if score <= best_score+2e-13:
                continue
            proposal = np.maximum(f+alpha*d,0.0)
            verified = exact(proposal)
            if verified > best_score:
                best_score = verified
                best = proposal
    if best is None:
        return init
    transitions = np.diff(np.r_[False,best > 0,False].astype(np.int8))
    starts = np.flatnonzero(transitions == 1)
    stops = np.flatnonzero(transitions == -1)
    packets = []
    for a,b in zip(starts,stops):
        if time.monotonic() > start + .90*budget_s:
            return init
        packets.append([int(a),best[a:b].tolist()])
    return {'length': n, 'packets': packets}
